class Counter {
    @Volatile
    private var counter = 0

    fun bad() {
        counter++
    }
}

class Counter {
    @Volatile
    private var counter = 0

    fun bad() {
        counter--
    }
}

class Counter {
    @Volatile
    private var count = 0

    fun bad() {
        count += 1
    }
}

import java.util.concurrent.atomic.AtomicInteger

class Counter {
    private val atomicCounter = AtomicInteger()

    fun good() {
        atomicCounter.incrementAndGet()
    }
}

class FlagHolder {
    @Volatile
    private var flag = false

    fun good() {
        flag = true
    }
}
